/*
	VIOC_uav_server.sqf - agregado por tools/vio_build.py (parche uav_request; copia configurada, no es del autor de la
	mision). Fuente: work/v6_build/uav_request/.

	Servidor de "PEDIR: Dron de reconocimiento (UAV)": CUALQUIER jugador de oeste o este (no solo el comandante) pide un
	dron SIN ARMAS de su bando que vuela alto en circulos sobre el punto que marco en el mapa y le da su camara por la
	terminal UAV. Lo paga con SUS fondos. El cliente (panel del mapa) esta en VIOC_uav_request.sqf.
	  - El cliente manda [jugador, posicion del clic, precio que vio] con remoteExecCall a VIOC_UAV_fnc_request (aqui), que
	    vuelve a validar TODO antes de cobrar: lobby, jugador vivo y de oeste/este, dron disponible para su bando, uno
	    activo por jugador, tope por bando (VIOC_UAVS_SIDECAP), espera por jugador (VIOC_UAV_COOLDOWN, cuenta desde que
	    se fue el dron anterior), presupuesto de IA de perf_cleanup (VIOC_PERF_AI_MAX / VIOC_PERF_AI_COUNT, si > 0),
	    posicion dentro del mapa y por ultimo los fondos (CTI_CO_FNC_GetFunds / CTI_CO_FNC_ChangeFunds dentro de isNil:
	    sin interrupciones entre mirar y descontar). Si el dron no se puede crear, se devuelve todo.
	  - Clase por nacion del bando (CTI_<BANDO>_MAINNATIONS = [nacion, mod]), comprobada en el juego (isClass, scope 2,
	    isUav, y VIOC_CA_fnc_banned de contemporary_assets si existe): EE.UU. -> CUP_B_USMC_DYN_MQ9 (MQ-9 Reaper de CUP con
	    pilones; CUP_B_USMC_MQ9 es scope 1) o B_UAV_02_dynamicLoadout_F; Rusia -> rhs_pchela1t_vvs / CUP_O_Pchela1T_RU
	    (primero el del mod principal) o O_UAV_02_dynamicLoadout_F; otras naciones modernas: el vanilla de su lado;
	    1968 (SOG principal) y Guerra Fria (BW/NVA): sin dron.
	  - Se crea volando ("FLY"), del bando, sin armas (todos los pilones vaciados con setPylonLoadout ""), con su
	    tripulacion IA de UAV (createVehicleCrew; si el grupo no es del bando, pasa a uno nuevo del bando), a
	    VIOC_UAVS_SPAWN m del objetivo del lado de lo propio mas cercano (HQ, estructuras o aerodromo propio de
	    airfields) y a altura segura; despues un punto LOITER sobre el clic (MQ-9: 1500 m sobre el suelo y circulo de
	    1000 m; Pchela: 500 m y 500 m; Greyhawk/Ababil: 1200 m y 800 m), descuidado, combate "BLUE" (nunca dispara),
	    setCaptive false, enlace de datos (setVehicleReportRemoteTargets / ReceiveRemoteTargets / ReportOwnPosition).
	    VIOC_KEEP = true mientras esta activo (perf_cleanup no lo toca). Combustible siempre lleno.
	  - Inteligencia (VIOC_UAV_INTEL): cada VIOC_UAVS_INTEL_T s, los enemigos que la tripulacion conoce (knowsAbout >=
	    1.5) a menos de VIOC_UAVS_INTEL_R m del centro van al cliente del jugador: los revela a su grupo y los marca en
	    su mapa (marcadores locales, se rehacen en cada pasada y se borran al final).
	  - Fin: al acabar el tiempo (VIOC_UAV_DURATION), si el jugador muere o se va, o al terminar la partida, el dron se
	    va hacia afuera y se borra cuando no hay jugadores a menos de VIOC_UAVS_GONE_R m (o a los VIOC_UAVS_GONE_T s);
	    se borran su tripulacion y su grupo; la terminal queda con el jugador. Si lo derriban: sin devolucion, aviso.
	Solo servidor. Parametros de lobby: VIOC_UAV_REQUEST, VIOC_UAV_PRICE, VIOC_UAV_DURATION, VIOC_UAV_COOLDOWN, VIOC_UAV_INTEL.
	Consola (servidor; en partida alojada vale "Ejecucion local"):
	    hint (call VIOC_UAV_fnc_status);                       drones activos, clases y esperas
	    [player, getPosATL player, -1] call VIOC_UAV_fnc_request;   pedir uno sobre tu posicion (se cobra)
	    [player] call VIOC_UAV_fnc_forceEnd;                  tu dron se retira ya
	    VIOC_UAVS_CD = [];                                    borra las esperas
*/
if (!isServer) exitWith {};
if (!isNil "VIOC_UAVS_STARTED") exitWith {};
VIOC_UAVS_STARTED = true;

//--- Parametros de lobby (en "Un jugador" la mision no los carga: valen los de por defecto).
VIOC_UAVS_MODE = missionNamespace getVariable ["VIOC_UAV_REQUEST", 1];
if !(VIOC_UAVS_MODE isEqualType 0) then {VIOC_UAVS_MODE = 1};
VIOC_UAVS_PRICE = missionNamespace getVariable ["VIOC_UAV_PRICE", 2500];
if !(VIOC_UAVS_PRICE isEqualType 0) then {VIOC_UAVS_PRICE = 2500};
VIOC_UAVS_PRICE = (round VIOC_UAVS_PRICE) max 0;
VIOC_UAVS_LIFE = missionNamespace getVariable ["VIOC_UAV_DURATION", 20];
if !(VIOC_UAVS_LIFE isEqualType 0) then {VIOC_UAVS_LIFE = 20};
VIOC_UAVS_LIFE = ((VIOC_UAVS_LIFE max 1) min 120) * 60;
VIOC_UAVS_CD_S = missionNamespace getVariable ["VIOC_UAV_COOLDOWN", 5];
if !(VIOC_UAVS_CD_S isEqualType 0) then {VIOC_UAVS_CD_S = 5};
VIOC_UAVS_CD_S = ((VIOC_UAVS_CD_S max 0) min 120) * 60;
VIOC_UAVS_INTEL = missionNamespace getVariable ["VIOC_UAV_INTEL", 1];
if !(VIOC_UAVS_INTEL isEqualType 0) then {VIOC_UAVS_INTEL = 1};
VIOC_UAVS_INTEL = VIOC_UAVS_INTEL > 0;

//--- Ajustes
VIOC_UAVS_SIDECAP = 3;		//--- drones activos por bando como maximo
VIOC_UAVS_SPAWN = 2500;		//--- m del objetivo donde aparece (del lado de lo propio mas cercano)
VIOC_UAVS_TICK = 5;			//--- s entre revisiones de cada dron
VIOC_UAVS_INTEL_T = 15;		//--- s entre pasadas de inteligencia
VIOC_UAVS_INTEL_R = 1500;	//--- m alrededor del centro del circulo
VIOC_UAVS_INTEL_K = 1.5;	//--- knowsAbout minimo de la tripulacion
VIOC_UAVS_INTEL_MAX = 40;	//--- marcadores como maximo por pasada
VIOC_UAVS_GONE_R = 2000;	//--- al irse, se borra cuando no hay jugadores a menos de esto
VIOC_UAVS_GONE_T = 180;		//--- o a los 3 min de irse

//--- Estado
VIOC_UAVS_ACTIVE = [];		//--- [uid, dron, grupo de la tripulacion, jugador, fin (time), bando, centro, clase]
VIOC_UAVS_CD = [];			//--- [uid, time en que se fue su ultimo dron]
VIOC_UAVS_CLASS = ["", ""];	//--- clase elegida para [oeste, este] ("" = sin dron)

//--- Identificador del jugador (UID; en "Un jugador" puede venir vacio).
VIOC_UAV_fnc_uid = {
	params ["_p"];
	private _u = getPlayerUID _p;
	if (_u == "") then {_u = "local"};
	_u
};

//--- "12:30 min" o "45 s"
VIOC_UAV_fnc_time = {
	params ["_s"];
	_s = round _s;
	if (_s < 60) exitWith {format ["%1 s", _s]};
	private _sec = _s mod 60;
	format ["%1:%2%3 min", floor (_s / 60), ["", "0"] select (_sec < 10), _sec]
};

//--- Segundos de espera que le quedan al jugador / anotar su ultimo dron.
VIOC_UAV_fnc_cdLeft = {
	params ["_uid"];
	private _i = VIOC_UAVS_CD findIf {(_x select 0) == _uid};
	if (_i < 0) exitWith {0};
	((((VIOC_UAVS_CD select _i) select 1) + VIOC_UAVS_CD_S) - time) max 0
};
VIOC_UAV_fnc_setCD = {
	params ["_uid", "_t"];
	VIOC_UAVS_CD = VIOC_UAVS_CD select {(_x select 0) != _uid};
	if (_t >= 0) then {VIOC_UAVS_CD pushBack [_uid, _t]};
};

//--- Presupuesto de IA de perf_cleanup (VIOC_PERF_AI_MAX > 0): true si caben _n unidades mas.
VIOC_UAV_fnc_perfOk = {
	params [["_n", 0]];
	private _max = missionNamespace getVariable ["VIOC_PERF_AI_MAX", 0];
	if (!(_max isEqualType 0) || {_max <= 0}) exitWith {true};
	private _cnt = missionNamespace getVariable ["VIOC_PERF_AI_COUNT", 0];
	if !(_cnt isEqualType 0) exitWith {true};
	(_cnt + _n) <= _max
};

//--- true si la politica de contemporary_assets quita la clase (false si ese parche no esta).
VIOC_UAV_fnc_banned = {
	params ["_c"];
	if (isNil "VIOC_CA_fnc_banned") exitWith {false};
	private _r = [_c] call VIOC_CA_fnc_banned;
	(!isNil "_r") && {_r isEqualTo true}
};

//--- Clases candidatas para el bando, en orden de preferencia.
VIOC_UAV_fnc_candidates = {
	params ["_side"];
	private _sog = missionNamespace getVariable ["CTI_SOG_DLC", -1];
	if (!isNil "CTI_US_SIDE" && {_sog isEqualType 0} && {_sog > 1}) exitWith {[]};	//--- 1968: sin drones
	private _nat = "";
	private _mod = -1;
	private _mn = missionNamespace getVariable [format ["CTI_%1_MAINNATIONS", _side], []];
	if (!isNil "CTI_US_SIDE" && {_mn isEqualType []} && {count _mn > 1}) then {
		private _n = _mn select 0;
		_mod = _mn select 1;
		if (_n isEqualTo (missionNamespace getVariable ["CTI_US_ID", 2])) then {_nat = "US"};
		if (_n isEqualTo (missionNamespace getVariable ["CTI_SOV_ID", 3])) then {_nat = "RU"};
		if ((_n isEqualTo (missionNamespace getVariable ["CTI_BW_ID", 0])) || {_n isEqualTo (missionNamespace getVariable ["CTI_NVA_ID", 1])}) then {_nat = "CW"};
	};
	//--- nacion principal sin dron propio: si EE.UU. o Rusia tambien estan en este bando (CTI_US_SIDE / CTI_SOV_SIDE = id del bando), se usa la suya
	if (_nat == "" && {!isNil "CTI_US_SIDE"}) then {
		private _sid = _side call CTI_CO_FNC_GetSideID;
		if ((missionNamespace getVariable ["CTI_US_SIDE", -1]) isEqualTo _sid) then {_nat = "US"} else {
			if ((missionNamespace getVariable ["CTI_SOV_SIDE", -1]) isEqualTo _sid) then {_nat = "RU"};
		};
	};
	private _rhs = _mod isEqualTo (missionNamespace getVariable ["CTI_RHS_ID", 5]);
	switch (true) do {
		case (_nat == "CW"): {[]};
		case (_nat == "US"): {["CUP_B_USMC_DYN_MQ9", "B_UAV_02_dynamicLoadout_F"]};
		case (_nat == "RU"): {if (_rhs) then {["rhs_pchela1t_vvs", "CUP_O_Pchela1T_RU", "O_UAV_02_dynamicLoadout_F"]} else {["CUP_O_Pchela1T_RU", "rhs_pchela1t_vvs", "O_UAV_02_dynamicLoadout_F"]}};
		case (_side == west): {["B_UAV_02_dynamicLoadout_F", "CUP_B_USMC_DYN_MQ9"]};
		case (_side == east): {["O_UAV_02_dynamicLoadout_F", "CUP_O_Pchela1T_RU", "rhs_pchela1t_vvs"]};
		default {[]};
	}
};

//--- Primera candidata que existe, es publica (scope 2), es un UAV aereo y no esta prohibida; las del mismo lado primero.
VIOC_UAV_fnc_pickClass = {
	params ["_side"];
	private _sn = [east, west, resistance] find _side;
	private _ok = [];
	{
		private _cfg = configFile >> "CfgVehicles" >> _x;
		if (isClass _cfg && {getNumber (_cfg >> "scope") >= 2} && {getNumber (_cfg >> "isUav") == 1} && {(configName _cfg) isKindOf "Air"} && {!([configName _cfg] call VIOC_UAV_fnc_banned)}) then {
			_ok pushBack [configName _cfg, (getNumber (_cfg >> "side")) == _sn];
		};
	} forEach ([_side] call VIOC_UAV_fnc_candidates);
	private _same = _ok select {_x select 1};
	if (count _same > 0) exitWith {(_same select 0) select 0};
	if (count _ok > 0) exitWith {(_ok select 0) select 0};
	""
};

//--- [altura sobre el suelo, radio del circulo, velocidad inicial m/s] segun el aparato.
VIOC_UAV_fnc_profile = {
	params ["_c"];
	if (_c isKindOf "CUP_MQ9_Base") exitWith {[1500, 1000, 55]};
	if ((_c isKindOf "CUP_Pchela1T_Base") || {_c isKindOf "rhs_pchela1t_base"}) exitWith {[500, 500, 40]};
	[1200, 800, 45]
};

//--- Lo propio mas cercano al objetivo: HQ, estructuras, aerodromos propios (airfields) o el marcador de reaparicion.
VIOC_UAV_fnc_home = {
	params ["_side", "_target"];
	private _c = [];
	private _hq = _side call CTI_CO_FNC_GetSideHQ;
	if (!isNil "_hq" && {_hq isEqualType objNull} && {!isNull _hq}) then {_c pushBack (getPosATL _hq)};
	private _sts = _side call CTI_CO_FNC_GetSideStructures;
	if (!isNil "_sts" && {_sts isEqualType []}) then {
		{if (_x isEqualType objNull && {!isNull _x}) then {_c pushBack (getPosATL _x)}} forEach _sts;
	};
	private _sid = _side call CTI_CO_FNC_GetSideID;
	private _tab = missionNamespace getVariable ["VIOC_AF_TABLE", []];
	if (_tab isEqualType []) then {
		{
			if ((_x isEqualType createHashMap) && {(_x getOrDefault ["owner", -9]) isEqualTo _sid}) then {
				private _p = _x getOrDefault ["ils", []];
				if (_p isEqualType [] && {count _p > 1}) then {_c pushBack _p};
			};
		} forEach _tab;
	};
	if (count _c == 0) then {
		private _m = format ["CTI_%1Respawn", _side];
		if (markerType _m != "") then {_c pushBack (markerPos _m)};
	};
	private _best = [];
	private _bd = 1e10;
	{
		private _d = _x distance2D _target;
		if (_d < _bd) then {_bd = _d; _best = _x};
	} forEach _c;
	_best
};

//--- true si hay algun jugador humano vivo a menos de _dist (2D) del objeto.
VIOC_UAV_fnc_playersNear = {
	params ["_obj", "_dist"];
	private _pl = allPlayers select {!(_x isKindOf "HeadlessClient_F")};
	if (!isMultiplayer && {hasInterface} && {!isNull player}) then {_pl pushBackUnique player};
	(_pl findIf {alive _x && {(_x distance2D _obj) < _dist}}) >= 0
};

//--- Jugador conectado con ese UID (o objNull).
VIOC_UAV_fnc_findPlayer = {
	params ["_uid"];
	private _c = allPlayers select {([_x] call VIOC_UAV_fnc_uid) == _uid};
	if (count _c == 0 && {!isMultiplayer} && {hasInterface} && {!isNull player}) then {_c = [player]};
	if (count _c > 0) then {_c select 0} else {objNull}
};

//--- El jugador que pidio el dron sigue vivo y conectado.
VIOC_UAV_fnc_playerOk = {
	params ["_p", "_uid"];
	!isNull _p && {alive _p} && {!isMultiplayer || {isPlayer _p}} && {([_p] call VIOC_UAV_fnc_uid) == _uid}
};

//--- Respuesta al jugador (aviso y chat). _cd = segundos de espera que le quedan (o -1); _data = datos del dron si salio bien.
VIOC_UAV_fnc_reply = {
	params ["_player", "_ok", "_text", ["_cd", -1], ["_data", []]];
	if (isNull _player) exitWith {};
	[_ok, _text, _cd, _data] remoteExecCall ["VIOC_UAVR_fnc_reply", _player];
};
VIOC_UAV_fnc_note = {
	params ["_player", "_text"];
	if (isNull _player) exitWith {};
	[_text] remoteExecCall ["VIOC_UAVR_fnc_note", _player];
};

//--- Quita del registro los que quedaron colgados (si el hilo de un dron muriera).
VIOC_UAV_fnc_prune = {
	{
		if ((isNull (_x select 1)) && {time > ((_x select 4) + 900)}) then {VIOC_UAVS_ACTIVE set [_forEachIndex, -1]};
	} forEach VIOC_UAVS_ACTIVE;
	VIOC_UAVS_ACTIVE = VIOC_UAVS_ACTIVE - [-1];
};

//--- Crea el dron volando, sin armas, con su tripulacion IA del bando y un circulo (LOITER) sobre el objetivo.
//--- Devuelve [dron, grupo, altura, radio] o el motivo (texto) si no se pudo.
VIOC_UAV_fnc_spawn = {
	params ["_side", "_cls", "_target"];
	([_cls] call VIOC_UAV_fnc_profile) params ["_alt", "_rad", "_spd"];
	private _home = [_side, _target] call VIOC_UAV_fnc_home;
	private _dir = if ((count _home > 1) && {(_home distance2D _target) > 50}) then {_target getDir _home} else {random 360};
	private _sp = _target getPos [VIOC_UAVS_SPAWN, _dir];
	_sp = [((_sp select 0) max 200) min (worldSize - 200), ((_sp select 1) max 200) min (worldSize - 200), 0];
	private _ground = ((getTerrainHeightASL _sp) max (getTerrainHeightASL _target)) max 0;
	private _uav = createVehicle [_cls, [_sp select 0, _sp select 1, _alt], [], 0, "FLY"];
	if (isNull _uav) exitWith {"no se pudo crear el dron"};
	_uav setDir (_sp getDir _target);
	_uav setPosASL [_sp select 0, _sp select 1, _ground + _alt];
	_uav setVelocityModelSpace [0, _spd, 0];
	//--- sin armas: se vacian todos los pilones (MQ-9 de CUP: 4 Hellfire por defecto; Greyhawk/Ababil: misiles o bombas)
	{_uav setPylonLoadout [_forEachIndex + 1, "", true]} forEach (getPylonMagazines _uav);
	private _cg = createVehicleCrew _uav;
	if (isNil "_cg" || {!(_cg isEqualType grpNull)} || {isNull _cg}) then {_cg = group (driver _uav)};
	private _crew = crew _uav;
	if (count _crew == 0) exitWith {deleteVehicle _uav; "el dron no recibio tripulacion IA"};
	if ((side _cg) != _side) then {
		//--- tripulacion de otro bando (clase de otro lado): pasa a un grupo nuevo del bando y se borra el grupo viejo
		private _old = _cg;
		_cg = createGroup [_side, true];
		if (!isNull _cg) then {
			_crew joinSilent _cg;
			if ((count units _old) == 0) then {deleteGroup _old};
		};
	};
	if (isNull _cg || {(side _cg) != _side}) exitWith {
		{deleteVehicle _x} forEach (crew _uav);
		deleteVehicle _uav;
		"no se pudo dar el dron a tu bando"
	};
	_cg setBehaviour "CARELESS";
	_cg setCombatMode "BLUE";
	_cg allowFleeing 0;
	{_x setCaptive false} forEach (crew _uav);
	_uav setCaptive false;
	_uav setFuel 1;
	_uav flyInHeight _alt;
	private _asl = ((getTerrainHeightASL _target) max 0) + _alt;
	_uav flyInHeightASL [_asl, _asl, _asl];
	_uav setVehicleReportRemoteTargets true;
	_uav setVehicleReceiveRemoteTargets true;
	_uav setVehicleReportOwnPosition true;
	_uav setVariable ["VIOC_KEEP", true, true];
	_uav setVariable ["vioc_uav", true, true];
	private _wp = _cg addWaypoint [_target, 0];
	_wp setWaypointType "LOITER";
	_wp setWaypointLoiterType "CIRCLE_L";
	_wp setWaypointLoiterRadius _rad;
	_wp setWaypointBehaviour "CARELESS";
	_wp setWaypointCombatMode "BLUE";
	_wp setWaypointSpeed "NORMAL";
	_cg setCurrentWaypoint _wp;
	if (!isNil "VIOC_ZEUS" && {VIOC_ZEUS isEqualType objNull} && {!isNull VIOC_ZEUS}) then {VIOC_ZEUS addCuratorEditableObjects [[_uav], true]};
	[_uav, _cg, _alt, _rad]
};

//--- Enemigos que la tripulacion conoce cerca del centro: [[[pos, tipo, lado (0 oeste, 1 este, 2 guerrilla), n o clase], ...], objetos].
VIOC_UAV_fnc_intelScan = {
	params ["_uav", "_side", "_center"];
	private _crew = (crew _uav) select {alive _x};
	if (count _crew == 0) exitWith {[[], []]};
	private _ents = [];
	private _objs = [];
	private _gl = [];
	private _gi = [];
	{
		private _t = _x;
		private _s = side _t;
		if ((_t != _uav) && {_s in [west, east, resistance]} && {_s != _side} && {(_side getFriend _s) < 0.6}) then {
			private _k = 0;
			{_k = _k max (_x knowsAbout _t)} forEach _crew;
			if (_k >= VIOC_UAVS_INTEL_K) then {
				_objs pushBack _t;
				private _si = [west, east, resistance] find _s;
				if (_t isKindOf "CAManBase") then {
					private _g = group _t;
					private _j = _gl find _g;
					if (_j < 0) then {
						_gl pushBack _g;
						_gi pushBack (count _ents);
						_ents pushBack [getPosATL _t, "inf", _si, 1];
					} else {
						private _e = _ents select (_gi select _j);
						_e set [3, (_e select 3) + 1];
					};
				} else {
					private _kind = switch (true) do {
						case (_t isKindOf "Plane"): {"plane"};
						case (_t isKindOf "Air"): {"air"};
						case (_t isKindOf "Ship"): {"naval"};
						case (_t isKindOf "StaticWeapon"): {"installation"};
						case (_t isKindOf "Tank"): {"armor"};
						case (_t isKindOf "Car"): {"motor_inf"};
						default {"unknown"};
					};
					_ents pushBack [getPosATL _t, _kind, _si, typeOf _t];
				};
			};
		};
		if ((count _ents) >= VIOC_UAVS_INTEL_MAX) exitWith {};
	} forEach (_center nearEntities [["CAManBase", "LandVehicle", "Air", "Ship"], VIOC_UAVS_INTEL_R]);
	[_ents, _objs]
};

//--- Vida de un dron (se corre con spawn): vigila, manda la inteligencia y al final lo retira y lo borra.
VIOC_UAV_fnc_life = {
	params ["_e"];
	_e params ["_uid", "_uav", "_cg", "_player", "_end", "_side", "_center", "_cls"];
	private _why = "";
	private _warned = false;
	private _nextIntel = time + 20;
	private _hadIntel = false;
	while {true} do {
		sleep VIOC_UAVS_TICK;
		if (isNull _uav || {!alive _uav}) exitWith {_why = "lost"};
		if !([_player, _uid] call VIOC_UAV_fnc_playerOk) exitWith {_why = "player"};
		if (missionNamespace getVariable ["CTI_GameOver", false]) exitWith {_why = "over"};
		if (_uav getVariable ["vioc_uav_end", false]) exitWith {_why = "forced"};
		if (time >= _end) exitWith {_why = "time"};
		if ((fuel _uav) < 0.5) then {_uav setFuel 1};
		if (!_warned && {(_end - time) <= 60}) then {
			_warned = true;
			[_player, "A tu dron le queda 1 minuto; despues se retira."] call VIOC_UAV_fnc_note;
		};
		if (VIOC_UAVS_INTEL && {time >= _nextIntel}) then {
			_nextIntel = time + VIOC_UAVS_INTEL_T;
			private _data = [_uav, _side, _center] call VIOC_UAV_fnc_intelScan;
			if ((count (_data select 0)) > 0 || {_hadIntel}) then {
				_hadIntel = (count (_data select 0)) > 0;
				[_data] remoteExecCall ["VIOC_UAVR_fnc_intel", _player];
			};
		};
	};
	//--- fuera del registro y espera desde ahora
	VIOC_UAVS_ACTIVE = VIOC_UAVS_ACTIVE select {!(((_x select 0) isEqualTo _uid) && {(_x select 1) isEqualTo _uav})};
	[_uid, time] call VIOC_UAV_fnc_setCD;
	private _pl = [_uid] call VIOC_UAV_fnc_findPlayer;
	private _pname = if (isNull _pl) then {_uid} else {name _pl};
	private _msg = switch (_why) do {
		case "lost": {"Tu dron fue derribado. No hay devolucion."};
		case "player": {"Tu dron se retira (moriste o saliste de la partida)."};
		case "time": {"Se acabo el tiempo de tu dron: se retira."};
		case "forced": {"Tu dron se retira (terminado desde la consola)."};
		default {"Tu dron se retira (la partida termino)."};
	};
	if (!isNull _pl) then {[_msg, VIOC_UAVS_CD_S] remoteExecCall ["VIOC_UAVR_fnc_ended", _pl]};
	diag_log format ["[VIOC uav] fin del dron de %1 (%2, %3): %4", _pname, _side, _cls, _why];
	if (_why == "lost") exitWith {
		[format ["[Dron] El dron de reconocimiento de %1 fue derribado.", _pname]] remoteExec ["systemChat", _side];
		{if (!isNull _x) then {deleteVehicle _x}} forEach (units _cg);
		if (!isNull _cg) then {deleteGroup _cg};
	};
	//--- se va hacia afuera (desde el centro, por donde esta ahora) y se borra cuando nadie lo ve
	_uav setVariable ["VIOC_KEEP", false, true];
	private _away = _center getPos [8000, _center getDir (getPosATL _uav)];
	private _wp = _cg addWaypoint [_away, 0];
	_wp setWaypointType "MOVE";
	_wp setWaypointBehaviour "CARELESS";
	_wp setWaypointCombatMode "BLUE";
	_cg setCurrentWaypoint _wp;
	private _t0 = time;
	waitUntil {
		sleep 5;
		isNull _uav || {!alive _uav} || {(time - _t0) > VIOC_UAVS_GONE_T} || {((time - _t0) > 10) && {!([_uav, VIOC_UAVS_GONE_R] call VIOC_UAV_fnc_playersNear)}}
	};
	if (!isNull _uav) then {
		{deleteVehicle _x} forEach (crew _uav);
		if (alive _uav) then {deleteVehicle _uav};
	};
	{if (!isNull _x) then {deleteVehicle _x}} forEach (units _cg);
	if (!isNull _cg) then {deleteGroup _cg};
};

//--- Pedido de un jugador (llega con remoteExecCall desde su cliente). Solo comprueba el remitente y responde.
VIOC_UAV_fnc_request = {
	params [["_player", objNull, [objNull]], ["_pos", [], [[]]], ["_seen", -1, [0]]];
	if (!isServer || {isNull _player}) exitWith {};
	private _ro = remoteExecutedOwner;
	if (isMultiplayer && {_ro > 0} && {_ro != (owner _player)}) exitWith {diag_log format ["[VIOC uav] pedido ignorado: la maquina %1 no controla a %2", _ro, name _player]};
	private _r = [_player, _pos, _seen] call VIOC_UAV_fnc_requestDo;
	if (_r != "ok") then {
		[_player, false, _r, [[_player] call VIOC_UAV_fnc_uid] call VIOC_UAV_fnc_cdLeft] call VIOC_UAV_fnc_reply;
		diag_log format ["[VIOC uav] pedido de %1 rechazado: %2", name _player, _r];
	};
};

//--- Valida, cobra y lanza. Devuelve "ok" o el motivo (texto para el jugador).
VIOC_UAV_fnc_requestDo = {
	params ["_player", "_pos", "_seen"];
	if (VIOC_UAVS_MODE <= 0) exitWith {"los drones a pedido estan desactivados en el lobby"};
	if (missionNamespace getVariable ["CTI_GameOver", false]) exitWith {"la partida termino"};
	if (!alive _player) exitWith {"tienes que estar vivo"};
	private _side = side group _player;
	private _si = [west, east] find _side;
	if (_si < 0) exitWith {"tu bando no puede pedir drones"};
	private _cls = VIOC_UAVS_CLASS select _si;
	if (_cls == "") exitWith {"tu bando no tiene un dron de reconocimiento en este escenario"};
	private _uid = [_player] call VIOC_UAV_fnc_uid;
	call VIOC_UAV_fnc_prune;
	if ((VIOC_UAVS_ACTIVE findIf {(_x select 0) == _uid}) >= 0) exitWith {"ya tienes un dron en el aire (uno por jugador)"};
	private _cd = [_uid] call VIOC_UAV_fnc_cdLeft;
	if (_cd > 0) exitWith {format ["todavia no: podras pedir otro dron en %1", [_cd] call VIOC_UAV_fnc_time]};
	if (({(_x select 5) == _side} count VIOC_UAVS_ACTIVE) >= VIOC_UAVS_SIDECAP) exitWith {format ["tu bando ya tiene %1 drones en el aire (maximo %1)", VIOC_UAVS_SIDECAP]};
	if !([2] call VIOC_UAV_fnc_perfOk) exitWith {"ahora hay demasiada IA en la partida (presupuesto VIOC_PERF_AI_MAX); prueba mas tarde"};
	if ((count _pos) < 2 || {!((_pos select 0) isEqualType 0)} || {!((_pos select 1) isEqualType 0)}) exitWith {"posicion no valida"};
	_pos = [_pos select 0, _pos select 1, 0];
	if ((_pos select 0) < 0 || {(_pos select 1) < 0} || {(_pos select 0) > worldSize} || {(_pos select 1) > worldSize}) exitWith {"la zona esta fuera del mapa"};
	private _price = VIOC_UAVS_PRICE;
	if (_seen >= 0 && {_price > (_seen + 1)}) exitWith {format ["el precio cambio: ahora cuesta %1 (viste %2); vuelve a pedirlo", _price, _seen]};
	//--- cobro (sin interrupciones entre mirar los fondos y descontarlos)
	private _grp = group _player;
	private _paid = false;
	private _funds = 0;
	isNil {
		_funds = [_grp, _side] call CTI_CO_FNC_GetFunds;
		if (isNil "_funds" || {!(_funds isEqualType 0)}) then {_funds = 0};
		if (_funds >= _price) then {
			if (_price > 0) then {[_grp, _side, -_price] call CTI_CO_FNC_ChangeFunds};
			_paid = true;
		};
	};
	if (!_paid) exitWith {format ["no te alcanza: cuesta %1 y tienes %2", _price, round _funds]};
	private _sp = [_side, _cls, _pos] call VIOC_UAV_fnc_spawn;
	if (_sp isEqualType "") exitWith {
		if (_price > 0) then {[_grp, _side, _price] call CTI_CO_FNC_ChangeFunds};
		format ["%1 (se te devolvieron los %2)", _sp, _price]
	};
	_sp params ["_uav", "_cg", "_alt", "_rad"];
	_uav setVariable ["vioc_uav_uid", _uid, true];
	private _e = [_uid, _uav, _cg, _player, time + VIOC_UAVS_LIFE, _side, _pos, _cls];
	VIOC_UAVS_ACTIVE pushBack _e;
	private _dn = getText (configFile >> "CfgVehicles" >> _cls >> "displayName");
	[_player, true, format ["%1 (sin armas) en camino a la cuadricula %2: llega en 1-2 min y vigila %3 min a unos %4 m de altura. Costo %5 (de tus fondos).", _dn, mapGridPosition _pos, round (VIOC_UAVS_LIFE / 60), _alt, _price], -1, [_uav, VIOC_UAVS_LIFE, _pos, _rad, _cls, _alt]] call VIOC_UAV_fnc_reply;
	[format ["[Dron] %1 pidio un dron de reconocimiento sobre la cuadricula %2.", name _player, mapGridPosition _pos]] remoteExec ["systemChat", _side];
	diag_log format ["[VIOC uav] dron de %1 (%2): %3 sobre %4, costo %5, %6 s", name _player, _side, _cls, mapGridPosition _pos, _price, VIOC_UAVS_LIFE];
	[_e] spawn VIOC_UAV_fnc_life;
	"ok"
};

//--- Termina ya el dron de un jugador (objeto o UID). Consola.
VIOC_UAV_fnc_forceEnd = {
	params [["_who", objNull]];
	private _uid = if (_who isEqualType "") then {_who} else {[_who] call VIOC_UAV_fnc_uid};
	{
		if (((_x select 0) == _uid) && {!isNull (_x select 1)}) then {(_x select 1) setVariable ["vioc_uav_end", true]};
	} forEach VIOC_UAVS_ACTIVE;
};

//--- Estado para la consola.
VIOC_UAV_fnc_status = {
	private _l = [format ["Drones activos: %1 (tope por bando %2). Clases: oeste %3, este %4. Precio %5, %6 min, espera %7 min, intel %8.", count VIOC_UAVS_ACTIVE, VIOC_UAVS_SIDECAP, VIOC_UAVS_CLASS select 0, VIOC_UAVS_CLASS select 1, VIOC_UAVS_PRICE, round (VIOC_UAVS_LIFE / 60), round (VIOC_UAVS_CD_S / 60), VIOC_UAVS_INTEL]];
	{
		_x params ["_uid", "_uav", "", "_pl", "_end", "_side", "_c", "_cls"];
		_l pushBack format ["- %1 (%2): %3, %4, quedan %5 s, cuadricula %6", if (isNull _pl) then {_uid} else {name _pl}, _side, _cls, if (alive _uav) then {format ["en el aire a %1 m", round ((getPosATL _uav) select 2)]} else {"perdido"}, round ((_end - time) max 0), mapGridPosition _c];
	} forEach VIOC_UAVS_ACTIVE;
	{_l pushBack format ["- espera de %1: %2 s", _x select 0, round ([_x select 0] call VIOC_UAV_fnc_cdLeft)]} forEach VIOC_UAVS_CD;
	_l joinString "\n"
};

//--- Para los clientes: clase de cada bando y datos del panel (una vez, cuando la mision esta lista).
[] spawn {
	waitUntil {sleep 2; !isNil "CTI_Init_Server"};
	VIOC_UAVS_CLASS = [west, east] apply {if (VIOC_UAVS_MODE > 0) then {[_x] call VIOC_UAV_fnc_pickClass} else {""}};
	private _prof = VIOC_UAVS_CLASS apply {if (_x == "") then {[0, 0]} else {([_x] call VIOC_UAV_fnc_profile) select [0, 2]}};
	VIOC_UAV_CFG = [VIOC_UAVS_MODE > 0, VIOC_UAVS_PRICE, VIOC_UAVS_LIFE, VIOC_UAVS_CD_S, VIOC_UAVS_INTEL, VIOC_UAVS_CLASS, _prof, VIOC_UAVS_SIDECAP];
	publicVariable "VIOC_UAV_CFG";
	diag_log format ["[VIOC uav] activo: modo %1, clases oeste %2 / este %3, precio %4, %5 min, espera %6 min, intel %7", VIOC_UAVS_MODE, VIOC_UAVS_CLASS select 0, VIOC_UAVS_CLASS select 1, VIOC_UAVS_PRICE, VIOC_UAVS_LIFE / 60, VIOC_UAVS_CD_S / 60, VIOC_UAVS_INTEL];
};

/*
	VIOC_uav_request.sqf - agregado por tools/vio_build.py (parche uav_request; copia configurada, no es del autor de la
	mision). Fuente: work/v6_build/uav_request/.

	Cliente de "PEDIR: Dron de reconocimiento (UAV)": CUALQUIER jugador (no solo el comandante) pide un dron SIN ARMAS
	de su bando (MQ-9 Reaper de EE.UU., Pchela-1T ruso...) que vuela alto en circulos sobre un punto del mapa y le da
	su camara por la terminal UAV. Se paga con SUS fondos.
	  - La accion abre el mapa con un panel a la derecha: clic = zona a vigilar (se ve el circulo que hara el dron);
	    el panel muestra el dron, la zona, el costo, la duracion, tus fondos y tu espera; CONFIRMAR manda el pedido al
	    servidor (VIOC_UAV_fnc_request en VIOC_uav_server.sqf), que valida todo otra vez y cobra; la respuesta llega
	    en un aviso. Esc / M / CANCELAR cierra sin pedir nada.
	  - Si sale bien: si no tienes una terminal UAV de tu bando, se te pone una en la ranura del GPS (el GPS que
	    tuvieras pasa a tu inventario si cabe; si no, queda en el suelo a tus pies), se conecta al dron y aparece la
	    accion temporal "VER CAMARA DEL DRON" (camara del artillero del dron; N cambia la vision: normal / nocturna /
	    termica). Tambien sirve la accion del juego "Abrir terminal UAV".
	  - Con la opcion de inteligencia, los enemigos que ve el dron salen en tu mapa (marcadores solo tuyos, cada 15 s)
	    y se revelan a tu grupo. Al terminar se borran; la terminal se queda contigo.
	Solo cliente (hasInterface). Parametros de lobby VIOC_UAV_REQUEST, VIOC_UAV_PRICE, VIOC_UAV_DURATION,
	VIOC_UAV_COOLDOWN, VIOC_UAV_INTEL (los aplica el servidor y los publica en VIOC_UAV_CFG).
	Consola (Ejecucion local): [] spawn VIOC_UAVR_fnc_open;   abre el panel;   VIOC_UAV_CFG   datos del servidor;
	    VIOC_UAVR_UAV   tu dron activo (objNull si no hay)
*/
if (!hasInterface) exitWith {};
if ((missionNamespace getVariable ["VIOC_UAV_REQUEST", 1]) <= 0) exitWith {};

VIOC_UAVR_POS = [];
VIOC_UAVR_OPEN = false;
VIOC_UAVR_CTRLS = [];
VIOC_UAVR_INFO = controlNull;
VIOC_UAVR_CD_UNTIL = -1;	//--- time local hasta el que dura tu espera (lo dice el servidor)
VIOC_UAVR_UAV = objNull;	//--- tu dron activo
VIOC_UAVR_END = -1;			//--- time local en que termina
VIOC_UAVR_ACT = [];			//--- [unidad, id] de la accion "VER CAMARA DEL DRON"
VIOC_UAVR_IMK = [];			//--- marcadores de inteligencia
VIOC_UAVR_MK = "vioc_uavr_target";
VIOC_UAVR_MKZ = "vioc_uavr_target_zone";
VIOC_UAVR_ZONE = "vioc_uavr_zone";
VIOC_UAVR_ZONE_C = "vioc_uavr_zone_c";

//--- Datos del servidor: [activo, precio, duracion s, espera s, intel, [clase oeste, clase este], [[altura, radio] oeste, este], tope por bando]
VIOC_UAVR_fnc_cfg = {missionNamespace getVariable ["VIOC_UAV_CFG", []]};

//--- [clase, altura, radio] del dron de tu bando, o [] si no hay.
VIOC_UAVR_fnc_mine = {
	private _cfg = call VIOC_UAVR_fnc_cfg;
	private _i = [west, east] find CTI_P_SideJoined;
	if (_i < 0 || {count _cfg < 7} || {!((_cfg select 0) isEqualTo true)}) exitWith {[]};
	private _c = (_cfg select 5) param [_i, ""];
	if !(_c isEqualType "") exitWith {[]};
	if (_c == "") exitWith {[]};
	private _p = (_cfg select 6) param [_i, [1000, 800]];
	if !(_p isEqualType []) then {_p = [1000, 800]};
	[_c, _p param [0, 1000], _p param [1, 800]]
};

//--- La accion PEDIR se ve si tu bando tiene dron (lo publica el servidor).
VIOC_UAVR_fnc_avail = {count (call VIOC_UAVR_fnc_mine) > 0};

//--- Texto seguro para parseText.
VIOC_UAVR_fnc_esc = {
	params [["_s", "", [""]]];
	private _o = [];
	{
		switch (_x) do {
			case 38: {_o append (toArray "&amp;")};
			case 60: {_o append (toArray "&lt;")};
			case 62: {_o append (toArray "&gt;")};
			default {_o pushBack _x};
		};
	} forEach (toArray _s);
	toString _o
};

VIOC_UAVR_fnc_name = {
	params ["_c"];
	private _n = getText (configFile >> "CfgVehicles" >> _c >> "displayName");
	if (_n == "") then {_n = _c};
	[_n] call VIOC_UAVR_fnc_esc
};

//--- Rehace el texto del panel.
VIOC_UAVR_fnc_refresh = {
	if (isNull VIOC_UAVR_INFO) exitWith {};
	private _cfg = call VIOC_UAVR_fnc_cfg;
	private _m = call VIOC_UAVR_fnc_mine;
	private _price = _cfg param [1, 2500];
	if !(_price isEqualType 0) then {_price = 2500};
	private _life = _cfg param [2, 1200];
	if !(_life isEqualType 0) then {_life = 1200};
	private _funds = call CTI_CL_FNC_GetPlayerFunds;
	if (isNil "_funds" || {!(_funds isEqualType 0)}) then {_funds = 0};
	private _cd = (VIOC_UAVR_CD_UNTIL - time) max 0;
	private _l = [];
	if (count _m == 0) then {
		_l pushBack "<t color='#F56363'>Tu bando no tiene dron de reconocimiento en este escenario.</t>";
	} else {
		_l pushBack format ["<t color='#9fd3ff'>Dron:</t> %1 (sin armas), a unos %2 m de altura, circulo de %3 m", [_m select 0] call VIOC_UAVR_fnc_name, _m select 1, _m select 2];
	};
	_l pushBack format ["<t color='#9fd3ff'>Zona:</t> %1", if (count VIOC_UAVR_POS < 2) then {"<t color='#F5D363'>haz clic en el mapa</t>"} else {format ["cuadricula %1", mapGridPosition VIOC_UAVR_POS]}];
	_l pushBack format ["<t color='#9fd3ff'>Costo:</t> $%1", _price];
	_l pushBack format ["<t color='#9fd3ff'>Duracion:</t> %1 min", round (_life / 60)];
	_l pushBack format ["<t color='#9fd3ff'>Tus fondos:</t> <t color='%2'>$%1</t>", round _funds, if (_funds >= _price) then {"#76F563"} else {"#F56363"}];
	if (!isNull VIOC_UAVR_UAV && {alive VIOC_UAVR_UAV}) then {
		_l pushBack format ["<t color='#F5D363'>Ya tienes un dron en el aire (quedan %1 min). Uno por jugador.</t>", ceil (((VIOC_UAVR_END - time) max 0) / 60)];
	} else {
		_l pushBack (if (_cd > 0) then {format ["<t color='#F5D363'>Espera: faltan %1 s</t>", round _cd]} else {"<t color='#9fd3ff'>Espera:</t> lista"});
	};
	if ((_cfg param [4, false]) isEqualTo true) then {_l pushBack "<t color='#aaaaaa'>Los enemigos que vea el dron saldran en tu mapa (cada 15 s).</t>"};
	VIOC_UAVR_INFO ctrlSetStructuredText parseText format ["<t size='0.85'>%1</t>", _l joinString "<br/>"];
};

//--- Clic en el mapa (evento MapSingleClick mientras el panel esta abierto): zona + circulo previsto.
VIOC_UAVR_fnc_click = {
	params ["_pos"];
	VIOC_UAVR_POS = [_pos select 0, _pos select 1, 0];
	deleteMarkerLocal VIOC_UAVR_MK;
	deleteMarkerLocal VIOC_UAVR_MKZ;
	private _r = (call VIOC_UAVR_fnc_mine) param [2, 800];
	private _z = createMarkerLocal [VIOC_UAVR_MKZ, VIOC_UAVR_POS];
	_z setMarkerShapeLocal "ELLIPSE";
	_z setMarkerSizeLocal [_r, _r];
	_z setMarkerBrushLocal "Border";
	_z setMarkerColorLocal "ColorBlue";
	private _m = createMarkerLocal [VIOC_UAVR_MK, VIOC_UAVR_POS];
	_m setMarkerTypeLocal "mil_objective";
	_m setMarkerColorLocal "ColorBlue";
	_m setMarkerTextLocal "Zona a vigilar (dron)";
	call VIOC_UAVR_fnc_refresh;
};

//--- CONFIRMAR: manda el pedido al servidor (que vuelve a validar todo y cobra).
VIOC_UAVR_fnc_confirm = {
	if (count (call VIOC_UAVR_fnc_mine) == 0) exitWith {hint "Tu bando no tiene dron de reconocimiento en este escenario."};
	if (count VIOC_UAVR_POS < 2) exitWith {hint "Haz clic en el mapa para elegir la zona a vigilar."};
	if (!isNull VIOC_UAVR_UAV && {alive VIOC_UAVR_UAV}) exitWith {hint "Ya tienes un dron en el aire (uno por jugador)."};
	if (VIOC_UAVR_CD_UNTIL > time) exitWith {hint format ["Todavia no puedes pedir otro dron: faltan %1 s.", round (VIOC_UAVR_CD_UNTIL - time)]};
	private _price = (call VIOC_UAVR_fnc_cfg) param [1, 2500];
	if !(_price isEqualType 0) then {_price = -1};
	[player, VIOC_UAVR_POS, _price] remoteExecCall ["VIOC_UAV_fnc_request", 2];
	systemChat "[Dron] Pedido enviado al mando...";
	VIOC_UAVR_OPEN = false;
	openMap false;
};

//--- Crea el panel sobre el mapa (pantalla 12). Devuelve true si pudo.
VIOC_UAVR_fnc_build = {
	params ["_d"];
	VIOC_UAVR_CTRLS = [];
	private _mk = {
		params ["_cls", "_pos"];
		private _c = _d ctrlCreate [_cls, -1];
		_c ctrlSetPosition _pos;
		_c ctrlCommit 0;
		VIOC_UAVR_CTRLS pushBack _c;
		_c
	};
	private _W = safeZoneW;
	private _H = safeZoneH;
	private _x0 = safeZoneX + _W * 0.735;
	private _y0 = safeZoneY + _H * 0.09;
	private _w = _W * 0.255;
	private _p = _W * 0.006;
	private _lh = _H * 0.034;
	private _iw = _w - 2 * _p;
	private _bw = (_iw - _p) / 2;
	private _bg = ["RscText", [_x0, _y0, _w, _H * 0.47]] call _mk;
	if (isNull _bg) exitWith {false};
	_bg ctrlSetBackgroundColor [0, 0, 0, 0.8];
	private _y = _y0 + _p;
	private _t = ["RscStructuredText", [_x0 + _p, _y, _iw, _lh * 3.2]] call _mk;
	_t ctrlSetStructuredText parseText "<t size='1.05' color='#9fe0ff'>PEDIR DRON DE RECONOCIMIENTO</t><br/><t size='0.8'>Clic en el mapa: la zona a vigilar. El dron (sin armas) vuela alto en circulos sobre ella y te da su camara por la terminal UAV. Se paga con TUS fondos.</t>";
	_y = _y + _lh * 3.3;
	private _info = ["RscStructuredText", [_x0 + _p, _y, _iw, _H * 0.26]] call _mk;
	_y = _y + _H * 0.26 + _p;
	private _ok = ["RscButton", [_x0 + _p, _y, _bw, _lh * 1.2]] call _mk;
	_ok ctrlSetText "CONFIRMAR";
	_ok ctrlSetBackgroundColor [0.2, 0.45, 0.75, 1];
	_ok ctrlAddEventHandler ["ButtonClick", "with missionNamespace do {call VIOC_UAVR_fnc_confirm}"];
	private _ko = ["RscButton", [_x0 + _p * 2 + _bw, _y, _bw, _lh * 1.2]] call _mk;
	_ko ctrlSetText "CANCELAR";
	_ko ctrlAddEventHandler ["ButtonClick", "with missionNamespace do {VIOC_UAVR_OPEN = false; openMap false}"];
	VIOC_UAVR_INFO = _info;
	true
};

//--- Cierra el panel: borra controles, marcadores del clic y evento del mapa.
VIOC_UAVR_fnc_close = {
	if (!isNil "VIOC_UAVR_EH") then {removeMissionEventHandler ["MapSingleClick", VIOC_UAVR_EH]; VIOC_UAVR_EH = nil};
	{if (!isNull _x) then {ctrlDelete _x}} forEach VIOC_UAVR_CTRLS;
	VIOC_UAVR_CTRLS = [];
	VIOC_UAVR_INFO = controlNull;
	deleteMarkerLocal VIOC_UAVR_MK;
	deleteMarkerLocal VIOC_UAVR_MKZ;
	VIOC_UAVR_OPEN = false;
};

//--- Accion "PEDIR: Dron de reconocimiento (UAV)" (se corre con spawn).
VIOC_UAVR_fnc_open = {
	if (VIOC_UAVR_OPEN) exitWith {};
	if !(call VIOC_UAVR_fnc_avail) exitWith {hint "Tu bando no tiene dron de reconocimiento en este escenario."};
	if (!alive player) exitWith {};
	VIOC_UAVR_OPEN = true;
	VIOC_UAVR_POS = [];
	openMap [true, false];
	private _t = diag_tickTime + 3;
	waitUntil {sleep 0.05; visibleMap || {diag_tickTime > _t}};
	private _d = findDisplay 12;
	if (!visibleMap || {isNull _d} || {!([_d] call VIOC_UAVR_fnc_build)}) exitWith {
		call VIOC_UAVR_fnc_close;
		hint "No se pudo abrir el panel del mapa. Prueba otra vez con el mapa cerrado.";
	};
	VIOC_UAVR_EH = addMissionEventHandler ["MapSingleClick", {
		params ["", "_pos"];
		[_pos] call VIOC_UAVR_fnc_click;
	}];
	call VIOC_UAVR_fnc_refresh;
	private _next = diag_tickTime + 1;
	waitUntil {
		sleep 0.1;
		if (diag_tickTime > _next) then {_next = diag_tickTime + 1; call VIOC_UAVR_fnc_refresh};
		!visibleMap || {!alive player} || {!VIOC_UAVR_OPEN}
	};
	call VIOC_UAVR_fnc_close;
	if (visibleMap) then {openMap false};
};

//--- Terminal UAV de tu bando en la ranura del GPS. Devuelve [true si quedo puesta, texto para el jugador].
VIOC_UAVR_fnc_terminal = {
	private _si = [east, west, resistance] find (side group player);
	if (_si < 0) exitWith {[false, "No hay terminal UAV para tu bando."]};
	private _want = ["O_UavTerminal", "B_UavTerminal", "I_UavTerminal"] select _si;
	//--- lo que ocupa la ranura del GPS (getUnitLoadout: indice 9 = [mapa, GPS/terminal, radio, brujula, reloj, NVG])
	private _slot = [];
	private _ai = (getUnitLoadout player) param [9, []];
	if (_ai isEqualType [] && {count _ai > 1} && {(_ai select 1) isEqualType ""} && {(_ai select 1) != ""}) then {_slot pushBack (_ai select 1)};
	{_slot pushBackUnique _x} forEach ((assignedItems player) select {(([_x] call BIS_fnc_itemType) param [1, ""]) in ["GPS", "UAVTerminal"]});
	if (({((([_x] call BIS_fnc_itemType) param [1, ""]) == "UAVTerminal") && {(getNumber (configFile >> "CfgWeapons" >> _x >> "ItemInfo" >> "side")) == _si}} count _slot) > 0) exitWith {[true, "Usas tu terminal UAV."]};
	if !(isClass (configFile >> "CfgWeapons" >> _want)) exitWith {[false, "No se encontro la terminal UAV de tu bando."]};
	private _notes = [];
	{
		private _it = _x;
		private _nm = getText (configFile >> "CfgWeapons" >> _it >> "displayName");
		if (_nm == "") then {_nm = _it};
		private _fits = player canAdd _it;
		player unlinkItem _it;
		if (_fits) then {
			player addItem _it;
			_notes pushBack format ["tu %1 paso a tu inventario", _nm];
		} else {
			private _h = createVehicle ["GroundWeaponHolder", getPosATL player, [], 0, "NONE"];
			_h addItemCargoGlobal [_it, 1];
			_notes pushBack format ["tu %1 no cabia en el inventario: quedo en el suelo a tus pies (recogelo pronto)", _nm];
		};
	} forEach _slot;
	player linkItem _want;
	private _ok = _want in (assignedItems player);
	if (!_ok) exitWith {[false, "No se pudo poner la terminal UAV en la ranura del GPS."]};
	[true, format ["Te di una terminal UAV (ranura del GPS)%1.", if (count _notes > 0) then {"; " + (_notes joinString "; ")} else {""}]]
};

//--- Accion "VER CAMARA DEL DRON": conecta la terminal si hace falta y pasa a la camara del artillero del dron.
VIOC_UAVR_fnc_camera = {
	private _uav = VIOC_UAVR_UAV;
	if (isNull _uav || {!alive _uav}) exitWith {hint "Tu dron ya no esta en el aire."};
	if !((getConnectedUAV player) isEqualTo _uav) then {
		private _t = call VIOC_UAVR_fnc_terminal;
		if (_t select 0) then {player connectTerminalToUAV _uav; sleep 0.5};
	};
	if !((getConnectedUAV player) isEqualTo _uav) exitWith {hint "No se pudo conectar tu terminal UAV al dron. Abre la terminal (accion 'Abrir terminal UAV' de la rueda del raton) y conectate a mano."};
	if (isNull (gunner _uav)) exitWith {hint "Este dron no tiene camara de artillero: usa la terminal UAV (accion 'Abrir terminal UAV')."};
	player action ["SwitchToUAVGunner", _uav];
	hint parseText "<t size='1.05' color='#9fe0ff'>Camara del dron</t><br/><br/><t align='left'>N: cambia la vision (normal / nocturna / termica).<br/>Para volver a tu soldado: rueda del raton, 'Soltar controles del UAV' (Release UAV controls).</t>";
};

//--- Respuesta del servidor (VIOC_UAV_fnc_reply). _data = [dron, duracion s, centro, radio, clase, altura] si salio bien.
VIOC_UAVR_fnc_reply = {
	params ["_ok", "_text", ["_cd", -1], ["_data", []]];
	if (_cd isEqualType 0 && {_cd >= 0}) then {VIOC_UAVR_CD_UNTIL = time + _cd};
	private _txt = [_text] call VIOC_UAVR_fnc_esc;
	systemChat format ["[Dron] %1", _text];
	if (!_ok) exitWith {
		hint parseText format ["<t size='1.1' color='#F56363'>Dron: no se pudo</t><br/><br/><t align='left'>%1</t>", _txt];
	};
	_data params [["_uav", objNull], ["_life", 1200], ["_center", []], ["_rad", 800]];
	VIOC_UAVR_END = time + _life;
	[_uav, _center, _rad, _txt] spawn VIOC_UAVR_fnc_setup;
};

//--- Prepara todo cuando el servidor acepta: busca el dron, zona en el mapa, terminal, conexion y accion de la camara.
VIOC_UAVR_fnc_setup = {
	params ["_uav", "_center", "_rad", "_txt"];
	if (isNull _uav) then {
		//--- el objeto puede tardar en llegar por la red: se busca por su marca
		private _uid = getPlayerUID player;
		if (_uid == "") then {_uid = "local"};
		private _t = time + 15;
		waitUntil {
			sleep 0.5;
			_uav = (vehicles select {((_x getVariable ["vioc_uav_uid", ""]) == _uid) && {alive _x}}) param [0, objNull];
			!isNull _uav || {time > _t}
		};
	};
	if (isNull _uav) exitWith {hint "Tu dron va en camino, pero no lo encuentro todavia: usa la terminal UAV (accion 'Abrir terminal UAV') en un momento."};
	VIOC_UAVR_UAV = _uav;
	//--- zona del dron en tu mapa (solo para ti)
	deleteMarkerLocal VIOC_UAVR_ZONE;
	deleteMarkerLocal VIOC_UAVR_ZONE_C;
	if (count _center > 1) then {
		private _z = createMarkerLocal [VIOC_UAVR_ZONE, _center];
		_z setMarkerShapeLocal "ELLIPSE";
		_z setMarkerSizeLocal [_rad, _rad];
		_z setMarkerBrushLocal "Border";
		_z setMarkerColorLocal "ColorBlue";
		private _c = createMarkerLocal [VIOC_UAVR_ZONE_C, _center];
		_c setMarkerTypeLocal (["o_uav", "b_uav", "n_uav"] select (([east, west, resistance] find (side group player)) max 0));
		_c setMarkerColorLocal "ColorBlue";
		_c setMarkerTextLocal "Tu dron: zona vigilada";
	};
	//--- terminal + conexion
	private _term = call VIOC_UAVR_fnc_terminal;
	if (_term select 0) then {
		player connectTerminalToUAV _uav;
		sleep 0.5;
	};
	private _con = (getConnectedUAV player) isEqualTo _uav;
	//--- accion temporal (se quita al terminar; la condicion la esconde si el dron ya no esta)
	if (count VIOC_UAVR_ACT == 2) then {(VIOC_UAVR_ACT select 0) removeAction (VIOC_UAVR_ACT select 1)};
	private _id = player addAction ["<t color='#9fe0ff'>VER CAMARA DEL DRON</t>", {[] spawn VIOC_UAVR_fnc_camera}, nil, 88, false, true, "", "alive _this && {!isNull VIOC_UAVR_UAV} && {alive VIOC_UAVR_UAV} && {cameraOn == vehicle _this}"];
	VIOC_UAVR_ACT = [player, _id];
	private _l = [_txt, [_term select 1] call VIOC_UAVR_fnc_esc];
	_l pushBack (if (_con) then {"Terminal conectada al dron."} else {"La terminal no se conecto sola: conectate desde la terminal UAV."});
	_l pushBack "Para ver lo que ve: accion 'VER CAMARA DEL DRON' (rueda del raton), o abre la terminal UAV (accion 'Abrir terminal UAV', o tu tecla de terminal si la tienes asignada) y elige la camara/torreta del dron.";
	_l pushBack "En la camara: N cambia la vision (normal / nocturna / termica). Para volver: rueda del raton, 'Soltar controles del UAV'.";
	if (((call VIOC_UAVR_fnc_cfg) param [4, false]) isEqualTo true) then {_l pushBack "Los enemigos que vea el dron saldran en tu mapa (cada 15 s)."};
	hint parseText format ["<t size='1.1' color='#76F563'>Dron de reconocimiento</t><br/><br/><t align='left'>%1</t>", _l joinString "<br/><br/>"];
};

//--- Aviso corto del servidor.
VIOC_UAVR_fnc_note = {
	params [["_text", "", [""]]];
	systemChat format ["[Dron] %1", _text];
	hint _text;
};

//--- Inteligencia del dron: [[[pos, tipo, lado, n o clase], ...], objetos]. Rehace los marcadores y revela a tu grupo.
VIOC_UAVR_fnc_clearIntel = {
	{deleteMarkerLocal _x} forEach VIOC_UAVR_IMK;
	VIOC_UAVR_IMK = [];
};
VIOC_UAVR_fnc_intel = {
	params [["_data", []]];
	call VIOC_UAVR_fnc_clearIntel;
	if (isNull VIOC_UAVR_UAV) exitWith {};
	_data params [["_ents", []], ["_objs", []]];
	private _pre = ["b_", "o_", "n_"];
	private _col = ["ColorWEST", "ColorEAST", "ColorGUER"];
	{
		_x params ["_p", "_kind", "_si", "_what"];
		private _m = createMarkerLocal [format ["vioc_uavr_i%1", _forEachIndex], _p];
		if (_m != "") then {
			_m setMarkerTypeLocal ((_pre param [_si, "o_"]) + _kind);
			_m setMarkerColorLocal (_col param [_si, "ColorRed"]);
			_m setMarkerTextLocal (if (_what isEqualType 0) then {format ["Infanteria x%1 (dron)", _what]} else {format ["%1 (dron)", getText (configFile >> "CfgVehicles" >> _what >> "displayName")]});
			VIOC_UAVR_IMK pushBack _m;
		};
	} forEach _ents;
	private _g = group player;
	{
		if (!isNull _x && {alive _x}) then {
			if (local _g) then {_g reveal [_x, 2]} else {player reveal [_x, 2]};
		};
	} forEach _objs;
};

//--- Fin del dron (el servidor lo retira o lo derribaron): suelta la camara, quita la accion y los marcadores.
VIOC_UAVR_fnc_ended = {
	params [["_text", "", [""]], ["_cd", -1]];
	private _uav = VIOC_UAVR_UAV;
	if (!isNull _uav) then {
		private _ctl = UAVControl _uav;
		if ((_ctl param [0, objNull]) isEqualTo player) then {
			private _u = if ((_ctl param [1, ""]) == "DRIVER") then {driver _uav} else {gunner _uav};
			if (!isNull _u) then {_u action ["BackFromUAV"]};
		};
		if ((getConnectedUAV player) isEqualTo _uav) then {player connectTerminalToUAV objNull};
	};
	VIOC_UAVR_UAV = objNull;
	VIOC_UAVR_END = -1;
	if (count VIOC_UAVR_ACT == 2) then {(VIOC_UAVR_ACT select 0) removeAction (VIOC_UAVR_ACT select 1)};
	VIOC_UAVR_ACT = [];
	call VIOC_UAVR_fnc_clearIntel;
	deleteMarkerLocal VIOC_UAVR_ZONE;
	deleteMarkerLocal VIOC_UAVR_ZONE_C;
	if (_cd isEqualType 0 && {_cd >= 0}) then {VIOC_UAVR_CD_UNTIL = time + _cd};
	systemChat format ["[Dron] %1", _text];
	hint parseText format ["<t size='1.05' color='#F5D363'>Dron de reconocimiento</t><br/><br/><t align='left'>%1%2</t>", [_text] call VIOC_UAVR_fnc_esc, if (_cd isEqualType 0 && {_cd > 0}) then {format ["<br/>Podras pedir otro en %1 min. La terminal UAV se queda contigo.", ceil (_cd / 60)]} else {"<br/>La terminal UAV se queda contigo."}];
};

class VIOC_UAV_REQUEST {
	title = "VIOC: Pedir un dron de reconocimiento (UAV sin armas que vuela alto sobre el punto que marques y te da su camara; accion PEDIR para cualquier jugador, pagado con tus fondos)";
	values[] = {0,1};
	texts[] = {"No","Si"};
	default = 1;
};
class VIOC_UAV_PRICE {
	title = "VIOC: Dron de reconocimiento: precio (de los fondos del jugador)";
	values[] = {1500,2500,4000};
	texts[] = {"1500","2500","4000"};
	default = 2500;
};
class VIOC_UAV_DURATION {
	title = "VIOC: Dron de reconocimiento: tiempo sobre la zona";
	values[] = {10,20,30};
	texts[] = {"10 min","20 min","30 min"};
	default = 20;
};
class VIOC_UAV_COOLDOWN {
	title = "VIOC: Dron de reconocimiento: espera para pedir otro (por jugador, desde que se va el anterior)";
	values[] = {0,2,5,10};
	texts[] = {"Sin espera","2 min","5 min","10 min"};
	default = 5;
};
class VIOC_UAV_INTEL {
	title = "VIOC: Dron de reconocimiento: marcar en tu mapa (y revelar a tu grupo) los enemigos que ve, cada 15 s";
	values[] = {0,1};
	texts[] = {"No","Si"};
	default = 1;
};

//--- VIOC: pedir un dron de reconocimiento (UAV) (cualquier jugador; accion PEDIR; parametros VIOC_UAV_REQUEST, VIOC_UAV_PRICE, VIOC_UAV_DURATION, VIOC_UAV_COOLDOWN y VIOC_UAV_INTEL; servidor en VIOC_uav_server.sqf, cliente en VIOC_uav_request.sqf)
if (isServer) then {call compile preprocessFileLineNumbers "VIOC_uav_server.sqf"};
if (hasInterface) then {call compile preprocessFileLineNumbers "VIOC_uav_request.sqf"};
